/**
 * Custom Worker entry (opennext.js.org/cloudflare/howtos/custom-worker).
 * The OpenNext handler serves the site; this file adds the Queue consumer and the Cron
 * trigger. Both forward to internal Next routes, so job code runs inside the Next bundle
 * with full access to cache revalidation, settings and the database helpers.
 */

// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- generated by `opennextjs-cloudflare build`
// @ts-ignore
import { default as handler } from "../.open-next/worker.js";

// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- generated by `opennextjs-cloudflare build`
// @ts-ignore
export { DOQueueHandler, DOShardedTagCache } from "../.open-next/worker.js";

type Env = { INTERNAL_JOB_SECRET?: string } & Record<string, unknown>;
type Ctx = { waitUntil(p: Promise<unknown>): void; passThroughOnException(): void };
type QueueMessage<T> = {
  id: string;
  body: T;
  attempts: number;
  ack(): void;
  retry(o?: { delaySeconds?: number }): void;
};
type Batch<T> = { queue: string; messages: QueueMessage<T>[] };
type Scheduled = { scheduledTime: number; cron: string };
type FetchHandler = { fetch(req: Request, env: Env, ctx: Ctx): Promise<Response> };

const app = handler as FetchHandler;

function internalRequest(path: string, env: Env, body: unknown): Request {
  return new Request(`https://propel.internal${path}`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${env.INTERNAL_JOB_SECRET ?? ""}`,
    },
    body: JSON.stringify(body),
  });
}

const worker = {
  fetch: app.fetch,

  /** One cron (`* * * * *`); the app decides what is due in the agency time zone. */
  async scheduled(event: Scheduled, env: Env, ctx: Ctx) {
    const res = await app.fetch(
      internalRequest("/api/internal/cron", env, { scheduledTime: event.scheduledTime }),
      env,
      ctx,
    );
    if (!res.ok) console.error(`[cron] ${res.status} ${await res.text()}`);
  },

  /** Jobs queue: each message carries a job_runs id. */
  async queue(batch: Batch<{ id: string }>, env: Env, ctx: Ctx) {
    for (const message of batch.messages) {
      try {
        const res = await app.fetch(
          internalRequest("/api/internal/jobs", env, { id: message.body.id }),
          env,
          ctx,
        );
        const data = (await res.json().catch(() => ({}))) as {
          outcome?: string;
          retryAfterSeconds?: number;
        };
        if (res.ok && data.outcome !== "retry") message.ack();
        else message.retry({ delaySeconds: data.retryAfterSeconds ?? 60 });
      } catch (err) {
        console.error("[queue] job dispatch failed", err);
        message.retry({ delaySeconds: 60 });
      }
    }
  },
};

export default worker;
